1	import { db } from "./db";
2	
3	// First-party event stream. Every product analytic — the activation funnel,
4	// retention cohorts, per-user journeys, attribution, the admin overview — is a
5	// query over this one table rather than its own bespoke tracking.
6	//
7	// Two rules keep it useful:
8	//
9	// 1. NAMES ARE A CLOSED SET. Free-text event names rot within weeks: three
10	//    spellings of the same thing, and every funnel query silently undercounts.
11	//    EVENTS below is the whole vocabulary; adding one is a deliberate edit.
12	// 2. PROPS ARE SMALL AND NON-PII. Ids, counts, short enum-ish strings. Never
13	//    prompt bodies, never generated content, never anything that would make
14	//    this table a second copy of user data with different retention rules.
15	
16	export const EVENTS = {
17	  // Acquisition — fire before an account exists, so userId is null.
18	  landingViewed: "landing.viewed",
19	  promptSubmittedAnon: "landing.prompt_submitted",
20	
21	  // Activation — the path the North Star measures.
22	  signedUp: "user.signed_up",
23	  projectCreated: "project.created",
24	  // Churn signal, and the counterweight to projectCreated: a funnel that only
25	  // counts creations reads as growth while people are deleting everything.
26	  projectDeleted: "project.deleted",
27	  buildStarted: "build.started",
28	  buildSucceeded: "build.succeeded",
29	  buildFailed: "build.failed",
30	  // Explicit thumbs up/down on a finished build — the only signal here that is
31	  // a direct statement of satisfaction rather than an inference from behaviour.
32	  buildRated: "build.rated",
33	  sitePublished: "project.published",
34	
35	  // Monetization.
36	  creditsExhausted: "credits.exhausted",
37	  spendCapReached: "credits.cap_reached",
38	  checkoutStarted: "billing.checkout_started",
39	  creditsPurchased: "billing.credits_purchased",
40	} as const;
41	
42	export type EventName = (typeof EVENTS)[keyof typeof EVENTS];
43	
44	/**
45	 * The North Star: a user reaching their first PUBLISHED build. Not first
46	 * signup, not first generation — the moment the product delivered the thing
47	 * it promises, a real site at a real URL.
48	 */
49	export const NORTH_STAR: EventName = EVENTS.sitePublished;
50	
51	type Props = Record<string, string | number | boolean | null | undefined>;
52	
53	/**
54	 * Record an event. Deliberately fire-and-forget: analytics must never fail a
55	 * user's request or add latency to a build. A dropped event is a small gap in
56	 * a dashboard; a thrown one would be a failed generation.
57	 */
58	export function track(name: EventName, opts: { userId?: string | null; props?: Props } = {}): void {
59	  void db.event
60	    .create({
61	      data: {
62	        name,
63	        userId: opts.userId ?? null,
64	        props: opts.props ? (JSON.parse(JSON.stringify(opts.props)) as object) : undefined,
65	      },
66	    })
67	    .catch((err) => {
68	      // Log and move on — see above.
69	      console.error(`[events] failed to record ${name}:`, err);
70	    });
71	}
72	
73	export type FunnelStep = { step: string; event: EventName; users: number; pctOfPrevious: number | null };
74	
75	/**
76	 * Activation funnel: signup → first project → first successful build → first
77	 * publish, counted in DISTINCT USERS rather than events. Counting events would
78	 * let one enthusiastic user look like retention.
79	 */
80	export async function activationFunnel(sinceDays = 30): Promise<FunnelStep[]> {
81	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
82	
83	  const steps: { step: string; event: EventName }[] = [
84	    { step: "Signed up", event: EVENTS.signedUp },
85	    { step: "Created a project", event: EVENTS.projectCreated },
86	    { step: "Built successfully", event: EVENTS.buildSucceeded },
87	    { step: "Published a site", event: EVENTS.sitePublished },
88	  ];
89	
90	  const out: FunnelStep[] = [];
91	  let previous: number | null = null;
92	
93	  for (const s of steps) {
94	    const rows = await db.event.findMany({
95	      where: { name: s.event, createdAt: { gte: since }, userId: { not: null } },
96	      distinct: ["userId"],
97	      select: { userId: true },
98	    });
99	    const users = rows.length;
100	    out.push({
101	      ...s,
102	      users,
103	      pctOfPrevious: previous === null || previous === 0 ? null : Math.round((users / previous) * 1000) / 10,
104	    });
105	    previous = users;
106	  }
107	
108	  return out;
109	}
110	
111	/**
112	 * Green-build-first-try: the share of successful builds that compiled with no
113	 * repair attempt. A roadmap kill-criterion — the jump to backend work is meant
114	 * to be gated on it, and nothing measured it before `Build.repairAttempts`.
115	 */
116	export async function greenBuildRate(sinceDays = 30): Promise<{
117	  succeeded: number;
118	  firstTry: number;
119	  rate: number | null;
120	}> {
121	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
122	  const where = { status: "SUCCEEDED", createdAt: { gte: since } };
123	
124	  const [succeeded, firstTry] = await Promise.all([
125	    db.build.count({ where }),
126	    db.build.count({ where: { ...where, repairAttempts: 0 } }),
127	  ]);
128	
129	  return {
130	    succeeded,
131	    firstTry,
132	    rate: succeeded === 0 ? null : Math.round((firstTry / succeeded) * 1000) / 10,
133	  };
134	}
135	
136	/**
137	 * What people ask for AFTER a build, ranked. This is the learning-mode
138	 * scoreboard: the top bucket is, in aggregate, what the first generation gets
139	 * wrong most often, and therefore what the next prompt change should target.
140	 *
141	 * Buckets come from a heuristic (lib/feedback-intent.ts) and are only
142	 * meaningful in aggregate — see the caveats in that file.
143	 */
144	export async function followUpIntents(
145	  sinceDays = 30,
146	): Promise<{ intent: string; count: number; pct: number }[]> {
147	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
148	
149	  const rows = await db.event.findMany({
150	    where: { name: EVENTS.buildStarted, createdAt: { gte: since } },
151	    select: { props: true },
152	  });
153	
154	  const counts = new Map<string, number>();
155	  for (const row of rows) {
156	    const intent = (row.props as { intent?: unknown } | null)?.intent;
157	    // Absent on first builds, which have no follow-up to classify.
158	    if (typeof intent !== "string") continue;
159	    counts.set(intent, (counts.get(intent) ?? 0) + 1);
160	  }
161	
162	  const total = [...counts.values()].reduce((a, b) => a + b, 0);
163	  return [...counts.entries()]
164	    .map(([intent, count]) => ({
165	      intent,
166	      count,
167	      pct: total === 0 ? 0 : Math.round((count / total) * 1000) / 10,
168	    }))
169	    .sort((a, b) => b.count - a.count);
170	}
171	
172	/** Thumbs up/down on finished builds. */
173	export async function buildRatings(sinceDays = 30): Promise<{
174	  up: number;
175	  down: number;
176	  rated: number;
177	  satisfaction: number | null;
178	}> {
179	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
180	
181	  const rows = await db.event.findMany({
182	    where: { name: EVENTS.buildRated, createdAt: { gte: since } },
183	    select: { props: true },
184	  });
185	
186	  let up = 0;
187	  let down = 0;
188	  for (const row of rows) {
189	    const rating = (row.props as { rating?: unknown } | null)?.rating;
190	    if (rating === "up") up++;
191	    else if (rating === "down") down++;
192	  }
193	
194	  const rated = up + down;
195	  return { up, down, rated, satisfaction: rated === 0 ? null : Math.round((up / rated) * 1000) / 10 };
196	}
