import type { ReactNode } from "react";

// Presentational helpers shared by the user list and the user detail page.
// Not a route — only page/layout/route filenames are routable — so this file
// is safe to sit inside app/admin/users/.
//
// Everything here mirrors the vocabulary already established in
// app/admin/page.tsx (rounded-xl hairline borders, text-sm, tabular-nums on
// every figure, monochrome except for status semantics) so the two pages read
// as one panel rather than two.

export function formatUsd(micros: number, decimals = 2): string {
  return `$${(micros / 1_000_000).toFixed(decimals)}`;
}

/** Whole-second UTC stamp, matching the recent-builds table on /admin. */
export function formatDateTime(d: Date): string {
  return d.toISOString().replace("T", " ").slice(0, 19);
}

export function formatDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

export function truncate(text: string, max = 60): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

export function statusClass(status: string): string {
  if (status === "SUCCEEDED") return "text-emerald-600 dark:text-emerald-400";
  if (status === "FAILED") return "text-red-600 dark:text-red-400";
  return "text-black/40 dark:text-white/40";
}

/**
 * CreditLedger.reason is free text and carries three different encodings —
 * plain words ("build", "signup_grant"), a Stripe session id, and the social
 * reward state machine (app/api/rewards/_lib.ts) whose reason string embeds an
 * identity HASH. Rendering those raw would put a 64-char hex blob in the
 * middle of a billing statement, so decode them into something a human can
 * scan. The raw string is still shown on hover via `title`.
 */
export function reasonLabel(reason: string): string {
  if (reason === "build") return "Build";
  if (reason === "signup_grant") return "Signup grant";
  if (reason.startsWith("stripe:")) return "Credit purchase";
  if (reason.startsWith("reward:")) {
    const parts = reason.split(":");
    const platform = parts[1] ?? "";
    const name = platform ? platform[0].toUpperCase() + platform.slice(1) : "Social";
    return parts[2] === "pending" ? `${name} reward (pending)` : `${name} reward`;
  }
  return reason.replace(/_/g, " ");
}

export function StatTile({
  label,
  value,
  hint,
  tone,
}: {
  label: string;
  value: ReactNode;
  hint?: ReactNode;
  tone?: "warn";
}) {
  return (
    <div className="rounded-xl border border-black/10 p-4 dark:border-white/10">
      <div className="text-xs text-black/50 dark:text-white/50">{label}</div>
      <div
        className={`mt-1 text-xl font-semibold tabular-nums ${
          tone === "warn" ? "text-amber-600 dark:text-amber-500" : ""
        }`}
      >
        {value}
      </div>
      {hint ? <div className="mt-1 text-xs text-black/50 dark:text-white/50">{hint}</div> : null}
    </div>
  );
}

export function Panel({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: ReactNode;
  children: ReactNode;
}) {
  return (
    <section className="rounded-xl border border-black/10 p-5 dark:border-white/10">
      <h2 className="text-sm font-medium">{title}</h2>
      {subtitle ? (
        <p className="mt-0.5 text-xs text-black/50 dark:text-white/50">{subtitle}</p>
      ) : null}
      <div className="mt-4">{children}</div>
    </section>
  );
}

export function Empty({ children }: { children: ReactNode }) {
  return (
    <div className="rounded-xl border border-dashed border-black/15 p-10 text-center text-sm text-black/60 dark:border-white/15 dark:text-white/60">
      {children}
    </div>
  );
}

/** Scrolling wrapper + hairline frame used by every table on both pages. */
export function TableFrame({ children }: { children: ReactNode }) {
  return (
    <div className="overflow-x-auto rounded-xl border border-black/10 dark:border-white/10">
      <table className="w-full text-left text-sm">{children}</table>
    </div>
  );
}

export function Th({
  children,
  align = "left",
}: {
  children: ReactNode;
  align?: "left" | "right";
}) {
  return (
    <th className={`px-4 py-2 font-medium ${align === "right" ? "text-right" : ""}`}>{children}</th>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import {
  Empty,
  StatTile,
  TableFrame,
  Th,
  formatDate,
  formatUsd,
  truncate,
} from "../users/ui";

export const dynamic = "force-dynamic";

const PAGE_SIZE = 25;

type SortKey = "recent" | "oldest" | "email" | "projects";

/**
 * Only DATABASE-NATIVE sorts are offered. Balance, lifetime spend and build
 * count are all derived from other tables and are computed per PAGE (see
 * below) — sorting the page by one of them would silently sort 25 arbitrary
 * rows rather than the whole table, which is worse than not offering it.
 */
const SORTS: Record<SortKey, { label: string; orderBy: Prisma.UserOrderByWithRelationInput }> = {
  recent: { label: "Newest", orderBy: { createdAt: "desc" } },
  oldest: { label: "Oldest", orderBy: { createdAt: "asc" } },
  email: { label: "Email", orderBy: { email: "asc" } },
  projects: { label: "Projects", orderBy: { projects: { _count: "desc" } } },
};

function isSortKey(v: unknown): v is SortKey {
  return typeof v === "string" && v in SORTS;
}

function first(v: string | string[] | undefined): string {
  if (Array.isArray(v)) return v[0] ?? "";
  return v ?? "";
}

function href(params: { q: string; sort: SortKey; page: number }): string {
  const sp = new URLSearchParams();
  if (params.q) sp.set("q", params.q);
  if (params.sort !== "recent") sp.set("sort", params.sort);
  if (params.page > 1) sp.set("page", String(params.page));
  const qs = sp.toString();
  return qs ? `/admin/users?${qs}` : "/admin/users";
}

// ── Per-page rollups ──────────────────────────────────────────────────────
// Everything below is keyed by userId and fetched for the CURRENT PAGE ONLY,
// in a fixed number of queries (6) regardless of how many users are on it.
// No query ever runs inside a loop over users.

type BalanceRow = { userId: string; balanceAfter: number };

type BuildRollupRow = {
  userId: string;
  builds: number;
  succeeded: number;
  failed: number;
  costMicros: bigint;
  creditsCharged: bigint;
  lastBuildAt: Date | null;
};

type Rollup = {
  balance: number;
  netDelta: number;
  spent: number;
  builds: number;
  succeeded: number;
  failed: number;
  costMicros: number;
  creditsCharged: number;
  lastBuildAt: Date | null;
};

const EMPTY_ROLLUP: Rollup = {
  balance: 0,
  netDelta: 0,
  spent: 0,
  builds: 0,
  succeeded: 0,
  failed: 0,
  costMicros: 0,
  creditsCharged: 0,
  lastBuildAt: null,
};

export default async function AdminUsersPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
  // is not an authorization boundary on its own (it does not re-render on
  // every navigation within the section). Same idiom as app/admin/page.tsx:
  // 404 rather than redirect, so a non-admin learns nothing about this path.
  if (!(await getAdminUser())) notFound();

  const sp = await searchParams;
  const q = first(sp.q).trim();
  const sortRaw = first(sp.sort);
  const sort: SortKey = isSortKey(sortRaw) ? sortRaw : "recent";
  const pageRaw = Number.parseInt(first(sp.page), 10);
  const page = Number.isFinite(pageRaw) && pageRaw > 0 ? pageRaw : 1;

  // Search by email, by display name, or by pasting a raw user id straight out
  // of a log line or a support ticket.
  const where: Prisma.UserWhereInput = q
    ? {
        OR: [
          { email: { contains: q, mode: "insensitive" } },
          { name: { contains: q, mode: "insensitive" } },
          { id: q },
        ],
      }
    : {};

  const [total, users] = await Promise.all([
    db.user.count({ where }),
    db.user.findMany({
      where,
      // `id` breaks ties so pagination is stable when timestamps collide.
      orderBy: [SORTS[sort].orderBy, { id: "asc" }],
      skip: (page - 1) * PAGE_SIZE,
      take: PAGE_SIZE,
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        createdAt: true,
        spendCapCredits: true,
        _count: { select: { projects: true } },
      },
    }),
  ]);

  const ids = users.map((u) => u.id);

  // ── Balance for many users, without one query each ────────────────────
  // lib/credits.ts `getBalance` reads `balanceAfter` off the user's NEWEST
  // ledger row. Postgres does that for a whole set of users in one pass with
  // DISTINCT ON: sort by (userId, createdAt DESC, id DESC) and keep the first
  // row per userId. `id` is the tiebreak so two rows written inside the same
  // millisecond still resolve deterministically to the same row Prisma's
  // findFirst would have picked.
  const balanceRows = ids.length
    ? await db.$queryRaw<BalanceRow[]>`
        SELECT DISTINCT ON (l."userId") l."userId", l."balanceAfter"
        FROM "CreditLedger" l
        WHERE l."userId" IN (${Prisma.join(ids)})
        ORDER BY l."userId", l."createdAt" DESC, l."id" DESC`
    : [];

  // Build has no userId — it hangs off Project — so the per-user build
  // rollup is one grouped join rather than a per-user count.
  const buildRows = ids.length
    ? await db.$queryRaw<BuildRollupRow[]>`
        SELECT p."userId",
               COUNT(*)::int AS "builds",
               COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS "succeeded",
               COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS "failed",
               COALESCE(SUM(b."costMicros"), 0)::bigint AS "costMicros",
               COALESCE(SUM(b."creditsCharged"), 0)::bigint AS "creditsCharged",
               MAX(b."createdAt") AS "lastBuildAt"
        FROM "Build" b
        JOIN "Project" p ON p."id" = b."projectId"
        WHERE p."userId" IN (${Prisma.join(ids)})
        GROUP BY p."userId"`
    : [];

  const [spentRows, netRows] = ids.length
    ? await Promise.all([
        db.creditLedger.groupBy({
          by: ["userId"],
          where: { userId: { in: ids }, delta: { lt: 0 } },
          _sum: { delta: true },
        }),
        // The ledger is append-only and starts at zero, so the sum of every
        // delta MUST equal the newest row's balanceAfter. Cheap to check here
        // (one grouped query for the page) and the only way to notice a
        // ledger that has drifted before a customer does.
        db.creditLedger.groupBy({
          by: ["userId"],
          where: { userId: { in: ids } },
          _sum: { delta: true },
        }),
      ])
    : [[], []];

  const rollups = new Map<string, Rollup>(ids.map((id) => [id, { ...EMPTY_ROLLUP }]));
  for (const r of balanceRows) {
    const u = rollups.get(r.userId);
    if (u) u.balance = r.balanceAfter;
  }
  for (const r of buildRows) {
    const u = rollups.get(r.userId);
    if (!u) continue;
    u.builds = Number(r.builds);
    u.succeeded = Number(r.succeeded);
    u.failed = Number(r.failed);
    u.costMicros = Number(r.costMicros);
    u.creditsCharged = Number(r.creditsCharged);
    u.lastBuildAt = r.lastBuildAt;
  }
  for (const r of spentRows) {
    const u = rollups.get(r.userId);
    // Deltas are negative for spend; show it as a positive number.
    if (u) u.spent = Math.abs(r._sum.delta ?? 0);
  }
  for (const r of netRows) {
    const u = rollups.get(r.userId);
    if (u) u.netDelta = r._sum.delta ?? 0;
  }

  const pageCount = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const drifted = [...rollups.values()].filter((r) => r.balance !== r.netDelta).length;

  return (
    <div className="mx-auto max-w-6xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin"
          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
        >
          ← kodely admin
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">Users</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          Read-only. Per-customer credits, builds and cost — the view that answers a billing
          email.
        </p>
      </div>

      <div className="mb-6 grid grid-cols-2 gap-4 sm:grid-cols-4">
        <StatTile label="Users matching" value={total} />
        <StatTile label="On this page" value={users.length} />
        <StatTile label="Page" value={`${page} / ${pageCount}`} />
        <StatTile
          label="Ledger drift"
          value={drifted}
          tone={drifted > 0 ? "warn" : undefined}
          hint="balanceAfter vs sum of deltas, this page"
        />
      </div>

      <form method="get" action="/admin/users" className="mb-6 flex flex-wrap items-center gap-2">
        <input
          type="search"
          name="q"
          defaultValue={q}
          placeholder="Search email, name or user id"
          aria-label="Search users"
          className="w-full max-w-sm rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus:border-black/30 dark:border-white/10 dark:placeholder:text-white/40 dark:focus:border-white/30"
        />
        <select
          name="sort"
          defaultValue={sort}
          aria-label="Sort users"
          className="rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none dark:border-white/10"
        >
          {(Object.keys(SORTS) as SortKey[]).map((k) => (
            <option key={k} value={k}>
              {SORTS[k].label}
            </option>
          ))}
        </select>
        <button
          type="submit"
          className="rounded-xl border border-black/10 px-3 py-2 text-sm font-medium hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
        >
          Search
        </button>
        {q ? (
          <Link
            href="/admin/users"
            className="text-sm text-black/50 underline-offset-4 hover:underline dark:text-white/50"
          >
            Clear
          </Link>
        ) : null}
      </form>

      {users.length === 0 ? (
        <Empty>{q ? `No users match “${truncate(q, 40)}”.` : "No users yet."}</Empty>
      ) : (
        <TableFrame>
          <thead>
            <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
              <Th>Email</Th>
              <Th>Signed up</Th>
              <Th>Role</Th>
              <Th align="right">Projects</Th>
              <Th align="right">Builds</Th>
              <Th align="right">Balance</Th>
              <Th align="right">Spent</Th>
              <Th align="right">Cost</Th>
            </tr>
          </thead>
          <tbody className="divide-y divide-black/10 dark:divide-white/10">
            {users.map((u) => {
              const r = rollups.get(u.id) ?? EMPTY_ROLLUP;
              const drift = r.balance !== r.netDelta;
              return (
                <tr key={u.id}>
                  <td className="max-w-xs px-4 py-2">
                    <Link
                      href={`/admin/users/${u.id}`}
                      className="font-medium underline-offset-4 hover:underline"
                    >
                      {truncate(u.email, 44)}
                    </Link>
                    {u.name ? (
                      <div className="text-xs text-black/50 dark:text-white/50">
                        {truncate(u.name, 44)}
                      </div>
                    ) : null}
                  </td>
                  <td className="whitespace-nowrap px-4 py-2 tabular-nums text-black/70 dark:text-white/70">
                    {formatDate(u.createdAt)}
                  </td>
                  <td className="px-4 py-2 text-black/70 dark:text-white/70">
                    {u.role === "ADMIN" ? (
                      <span className="font-medium">ADMIN</span>
                    ) : (
                      <span className="text-black/50 dark:text-white/50">{u.role}</span>
                    )}
                  </td>
                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {u._count.projects}
                  </td>
                  <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {r.builds}
                    {r.builds > 0 ? (
                      <span className="ml-2 text-xs">
                        <span className="text-emerald-600 dark:text-emerald-400">{r.succeeded}</span>
                        <span className="text-black/30 dark:text-white/30"> / </span>
                        <span className="text-red-600 dark:text-red-400">{r.failed}</span>
                      </span>
                    ) : null}
                  </td>
                  <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums">
                    <span className={r.balance === 0 ? "text-red-600 dark:text-red-400" : ""}>
                      {r.balance}
                    </span>
                    {drift ? (
                      <span
                        className="ml-1 text-amber-600 dark:text-amber-500"
                        title={`Ledger drift: newest balanceAfter is ${r.balance} but deltas sum to ${r.netDelta}`}
                      >
                        !
                      </span>
                    ) : null}
                    {u.spendCapCredits !== null ? (
                      <div className="text-xs text-black/50 dark:text-white/50">
                        cap {u.spendCapCredits}
                      </div>
                    ) : null}
                  </td>
                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {r.spent}
                  </td>
                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {formatUsd(r.costMicros, 4)}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </TableFrame>
      )}

      <div className="mt-4 flex items-center justify-between text-sm">
        <span className="text-black/50 dark:text-white/50">
          {total === 0
            ? "0 users"
            : `${(page - 1) * PAGE_SIZE + 1}–${Math.min(page * PAGE_SIZE, total)} of ${total}`}
        </span>
        <span className="flex gap-2">
          {page > 1 ? (
            <Link
              href={href({ q, sort, page: page - 1 })}
              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
            >
              Previous
            </Link>
          ) : null}
          {page < pageCount ? (
            <Link
              href={href({ q, sort, page: page + 1 })}
              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
            >
              Next
            </Link>
          ) : null}
        </span>
      </div>

      <p className="mt-6 text-xs text-black/50 dark:text-white/50">
        Balance is the newest ledger row&apos;s balanceAfter, matching lib/credits.ts. Spent is the
        sum of negative deltas. Cost is real model spend across every build on the user&apos;s
        projects, charged or not — failed builds cost us money and are never billed.
      </p>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { MICROS_PER_CREDIT } from "@/lib/credits";
import {
  Empty,
  Panel,
  StatTile,
  TableFrame,
  Th,
  formatDateTime,
  formatUsd,
  reasonLabel,
  statusClass,
  truncate,
} from "../ui";

export const dynamic = "force-dynamic";

// Bounded reads. A support question is answered from the recent tail, and an
// unbounded findMany on a heavy account would be the one slow query on this
// panel. Each table says so when it is showing a truncated view.
const LEDGER_LIMIT = 250;
const BUILD_LIMIT = 100;
const EVENT_LIMIT = 100;

/** Rolling window used by the self-imposed spend cap in lib/credits.ts. */
const CAP_WINDOW_DAYS = 30;

function propsSummary(props: unknown): string {
  if (props === null || typeof props !== "object" || Array.isArray(props)) return "";
  return Object.entries(props as Record<string, unknown>)
    .map(([k, v]) => `${k}=${typeof v === "string" ? v : JSON.stringify(v)}`)
    .join("  ·  ");
}

export default async function AdminUserDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  // Defense in depth — see app/admin/page.tsx. The layout gate is the primary
  // one, but a layout must not be the sole authorization boundary.
  if (!(await getAdminUser())) notFound();

  const { id } = await params;

  const user = await db.user.findUnique({
    where: { id },
    select: {
      id: true,
      email: true,
      name: true,
      role: true,
      createdAt: true,
      spendCapCredits: true,
      googleId: true,
      passwordHash: true,
      stripeCustomerId: true,
    },
  });
  if (!user) notFound();

  const capSince = new Date(Date.now() - CAP_WINDOW_DAYS * 24 * 60 * 60 * 1000);

  const [
    projects,
    builds,
    ledger,
    events,
    buildTotals,
    buildStatuses,
    grantedAgg,
    spentAgg,
    ledgerTotal,
    buildTotal,
    eventTotal,
    windowSpendAgg,
  ] = await Promise.all([
    db.project.findMany({
      where: { userId: id },
      orderBy: { createdAt: "desc" },
      select: {
        id: true,
        name: true,
        slug: true,
        createdAt: true,
        updatedAt: true,
        publishedAt: true,
        _count: { select: { builds: true, files: true, messages: true } },
      },
    }),
    db.build.findMany({
      where: { project: { userId: id } },
      orderBy: { createdAt: "desc" },
      take: BUILD_LIMIT,
      select: {
        id: true,
        createdAt: true,
        endedAt: true,
        status: true,
        model: true,
        inputTokens: true,
        outputTokens: true,
        costMicros: true,
        creditsCharged: true,
        repairAttempts: true,
        prompt: true,
        error: true,
        project: { select: { id: true, name: true } },
      },
    }),
    db.creditLedger.findMany({
      where: { userId: id },
      // Same ordering as lib/credits.ts getBalance, with `id` as a stable
      // tiebreak — so row 0 here IS the row that defines the balance.
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      take: LEDGER_LIMIT,
      select: {
        id: true,
        createdAt: true,
        delta: true,
        reason: true,
        balanceAfter: true,
        build: { select: { id: true, status: true, project: { select: { name: true } } } },
      },
    }),
    db.event.findMany({
      where: { userId: id },
      // Served straight off the @@index([userId, createdAt]) on Event.
      orderBy: { createdAt: "desc" },
      take: EVENT_LIMIT,
      select: { id: true, name: true, props: true, createdAt: true },
    }),
    db.build.aggregate({
      where: { project: { userId: id } },
      _sum: { costMicros: true, creditsCharged: true, inputTokens: true, outputTokens: true },
    }),
    db.build.groupBy({
      by: ["status"],
      where: { project: { userId: id } },
      _count: { _all: true },
    }),
    db.creditLedger.aggregate({ where: { userId: id, delta: { gt: 0 } }, _sum: { delta: true } }),
    db.creditLedger.aggregate({ where: { userId: id, delta: { lt: 0 } }, _sum: { delta: true } }),
    db.creditLedger.count({ where: { userId: id } }),
    db.build.count({ where: { project: { userId: id } } }),
    db.event.count({ where: { userId: id } }),
    db.creditLedger.aggregate({
      where: { userId: id, delta: { lt: 0 }, createdAt: { gte: capSince } },
      _sum: { delta: true },
    }),
  ]);

  const balance = ledger[0]?.balanceAfter ?? 0;
  const granted = grantedAgg._sum.delta ?? 0;
  const spent = Math.abs(spentAgg._sum.delta ?? 0);
  const windowSpend = Math.abs(windowSpendAgg._sum.delta ?? 0);

  const costMicros = buildTotals._sum.costMicros ?? 0;
  const creditsCharged = buildTotals._sum.creditsCharged ?? 0;
  const revenueMicros = creditsCharged * MICROS_PER_CREDIT;
  const marginMicros = revenueMicros - costMicros;

  const succeeded = buildStatuses.find((s) => s.status === "SUCCEEDED")?._count._all ?? 0;
  const failed = buildStatuses.find((s) => s.status === "FAILED")?._count._all ?? 0;

  // ── Integrity checks, computed from rows already in hand ────────────────
  // The ledger is append-only and starts at zero, so balanceAfter must be the
  // running sum of every delta. Walk the fetched window oldest-first; only
  // anchor on the very first row when the whole ledger is on the page.
  const chrono = [...ledger].reverse();
  const brokenRows = new Set<string>();
  if (chrono.length > 0 && ledgerTotal <= LEDGER_LIMIT && chrono[0].balanceAfter !== chrono[0].delta) {
    brokenRows.add(chrono[0].id);
  }
  for (let i = 1; i < chrono.length; i++) {
    if (chrono[i - 1].balanceAfter + chrono[i].delta !== chrono[i].balanceAfter) {
      brokenRows.add(chrono[i].id);
    }
  }

  // The anti-bill-shock contract: a build that FAILED is recorded with its
  // true cost and charged ZERO. Anything else is a refund waiting to happen,
  // and is the literal subject of "my build failed and I was charged".
  const chargedFailures = builds.filter((b) => b.status !== "SUCCEEDED" && b.creditsCharged > 0);
  const chargesOnBadBuilds = ledger.filter(
    (l) => l.build !== null && l.delta < 0 && l.build.status !== "SUCCEEDED",
  );

  const maxBalance = Math.max(1, ...ledger.map((l) => l.balanceAfter));
  const capRemaining =
    user.spendCapCredits === null ? null : Math.max(0, user.spendCapCredits - windowSpend);

  const signInMethods = [
    user.passwordHash ? "password" : null,
    user.googleId ? "google" : null,
  ].filter(Boolean);

  return (
    <div className="mx-auto max-w-6xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin/users"
          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
        >
          ← Users
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">{user.email}</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          {user.name ? `${user.name} · ` : ""}
          {user.role} · signed up {formatDateTime(user.createdAt)} ·{" "}
          {signInMethods.length > 0 ? signInMethods.join(" + ") : "no sign-in method"}
          {user.stripeCustomerId ? " · stripe customer" : ""}
        </p>
        <p className="mt-1 font-mono text-xs text-black/40 dark:text-white/40">{user.id}</p>
      </div>

      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-6">
        <StatTile
          label="Credit balance"
          value={<span className={balance === 0 ? "text-red-600 dark:text-red-400" : ""}>{balance}</span>}
          hint={
            user.spendCapCredits === null
              ? "no spend cap set"
              : `cap ${user.spendCapCredits}/30d · ${capRemaining} left`
          }
        />
        <StatTile label="Lifetime granted" value={granted} />
        <StatTile label="Lifetime spent" value={spent} hint={`${windowSpend} in last 30d`} />
        <StatTile
          label="Builds"
          value={
            <>
              <span className="text-emerald-600 dark:text-emerald-400">{succeeded}</span>
              <span className="text-black/30 dark:text-white/30"> / </span>
              <span className="text-red-600 dark:text-red-400">{failed}</span>
            </>
          }
          hint={`${buildTotal} total`}
        />
        <StatTile
          label="Imputed cost"
          value={formatUsd(costMicros, 4)}
          hint={`${creditsCharged} credits charged`}
        />
        <StatTile
          label="Margin"
          value={formatUsd(marginMicros, 4)}
          hint="credits charged at list, minus real spend"
        />
      </div>

      {(chargedFailures.length > 0 || chargesOnBadBuilds.length > 0 || brokenRows.size > 0) && (
        <div className="mb-8 rounded-xl border border-amber-500/40 bg-amber-500/5 p-5 text-sm">
          <h2 className="text-sm font-medium text-amber-700 dark:text-amber-500">Needs a look</h2>
          <ul className="mt-2 list-disc space-y-1 pl-5 text-black/70 dark:text-white/70">
            {chargedFailures.length > 0 && (
              <li>
                {chargedFailures.length} build(s) in the recent window were charged despite not
                succeeding. Failed builds are never supposed to be billed.
              </li>
            )}
            {chargesOnBadBuilds.length > 0 && (
              <li>
                {chargesOnBadBuilds.length} ledger charge(s) point at a build that is not in
                SUCCEEDED state.
              </li>
            )}
            {brokenRows.size > 0 && (
              <li>
                {brokenRows.size} ledger row(s) have a balanceAfter that does not equal the running
                sum of deltas. Marked with ! in the statement below.
              </li>
            )}
          </ul>
        </div>
      )}

      <div className="mb-8">
        <Panel
          title="Credit statement"
          subtitle={
            <>
              Newest first. Every row is one append-only ledger entry; the balance column is the
              account balance immediately after it.
              {ledgerTotal > ledger.length
                ? ` Showing the most recent ${ledger.length} of ${ledgerTotal} entries.`
                : ""}
            </>
          }
        >
          {ledger.length === 0 ? (
            <Empty>No credit activity — not even a signup grant.</Empty>
          ) : (
            <TableFrame>
              <thead>
                <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
                  <Th>When</Th>
                  <Th>What</Th>
                  <Th>Against</Th>
                  <Th align="right">Change</Th>
                  <Th align="right">Balance</Th>
                  <Th>&nbsp;</Th>
                </tr>
              </thead>
              <tbody className="divide-y divide-black/10 dark:divide-white/10">
                {ledger.map((l) => {
                  const broken = brokenRows.has(l.id);
                  const badCharge = l.build !== null && l.delta < 0 && l.build.status !== "SUCCEEDED";
                  return (
                    <tr key={l.id}>
                      <td className="whitespace-nowrap px-4 py-2 tabular-nums text-black/70 dark:text-white/70">
                        {formatDateTime(l.createdAt)}
                      </td>
                      <td className="px-4 py-2" title={l.reason}>
                        {reasonLabel(l.reason)}
                      </td>
                      <td className="max-w-xs px-4 py-2 text-black/60 dark:text-white/60">
                        {l.build ? (
                          <>
                            {truncate(l.build.project.name, 34)}{" "}
                            <span className={statusClass(l.build.status)}>{l.build.status}</span>
                            {badCharge ? (
                              <span
                                className="ml-1 text-amber-600 dark:text-amber-500"
                                title="Charged against a build that did not succeed"
                              >
                                !
                              </span>
                            ) : null}
                          </>
                        ) : (
                          <span className="text-black/30 dark:text-white/30">—</span>
                        )}
                      </td>
                      <td
                        className={`whitespace-nowrap px-4 py-2 text-right font-medium tabular-nums ${
                          l.delta > 0
                            ? "text-emerald-600 dark:text-emerald-400"
                            : l.delta < 0
                              ? "text-red-600 dark:text-red-400"
                              : "text-black/40 dark:text-white/40"
                        }`}
                      >
                        {l.delta > 0 ? `+${l.delta}` : l.delta}
                      </td>
                      <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums">
                        <span className={l.balanceAfter === 0 ? "text-red-600 dark:text-red-400" : ""}>
                          {l.balanceAfter}
                        </span>
                        {broken ? (
                          <span
                            className="ml-1 text-amber-600 dark:text-amber-500"
                            title="balanceAfter does not match the running sum of deltas"
                          >
                            !
                          </span>
                        ) : null}
                      </td>
                      <td className="w-32 px-4 py-2">
                        {/* Balance trajectory — makes "when did they run dry" a
                            glance rather than a column of numbers to diff. */}
                        <span className="block h-1.5 w-full overflow-hidden rounded-full bg-black/10 dark:bg-white/10">
                          <span
                            className="block h-full rounded-full bg-black/70 dark:bg-white/70"
                            style={{ width: `${(l.balanceAfter / maxBalance) * 100}%` }}
                          />
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </TableFrame>
          )}
        </Panel>
      </div>

      <div className="mb-8">
        <Panel
          title="Projects"
          subtitle={`${projects.length} project(s). Read-only — this panel never edits customer work.`}
        >
          {projects.length === 0 ? (
            <Empty>No projects.</Empty>
          ) : (
            <TableFrame>
              <thead>
                <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
                  <Th>Name</Th>
                  <Th>Slug</Th>
                  <Th>Published</Th>
                  <Th align="right">Builds</Th>
                  <Th align="right">Files</Th>
                  <Th align="right">Messages</Th>
                  <Th>Created</Th>
                  <Th>Updated</Th>
                </tr>
              </thead>
              <tbody className="divide-y divide-black/10 dark:divide-white/10">
                {projects.map((p) => (
                  <tr key={p.id}>
                    <td className="max-w-xs px-4 py-2">{truncate(p.name, 44)}</td>
                    <td className="max-w-xs px-4 py-2 font-mono text-xs text-black/60 dark:text-white/60">
                      {truncate(p.slug, 44)}
                    </td>
                    <td className="whitespace-nowrap px-4 py-2 tabular-nums">
