import { createRequire } from "node:module";
const require = createRequire("C:/Users/edmem/kodely-prod/x.js");
const { PrismaClient, Prisma } = require("@prisma/client");
const db = new PrismaClient();

const PAGE_SIZE = 25;

// ── Exactly the list page's query set ────────────────────────────────────
for (const q of ["", "kodely", "HAX", "cmt33c6xz0000u7skv25xld9t", "nomatch"]) {
  const where = q
    ? {
        OR: [
          { email: { contains: q, mode: "insensitive" } },
          { name: { contains: q, mode: "insensitive" } },
          { id: q },
        ],
      }
    : {};
  const total = await db.user.count({ where });
  console.log(`SEARCH q=${JSON.stringify(q)} -> ${total}`);
}

for (const orderBy of [
  [{ createdAt: "desc" }, { id: "asc" }],
  [{ createdAt: "asc" }, { id: "asc" }],
  [{ email: "asc" }, { id: "asc" }],
  [{ projects: { _count: "desc" } }, { id: "asc" }],
]) {
  const users = await db.user.findMany({
    orderBy,
    skip: 0,
    take: PAGE_SIZE,
    select: {
      id: true, email: true, name: true, role: true, createdAt: true,
      spendCapCredits: true, _count: { select: { projects: true } },
    },
  });
  console.log("SORT", JSON.stringify(orderBy), "->", users.map((u) => `${u.email}(${u._count.projects})`).join(", "));
}

const users = await db.user.findMany({ orderBy: [{ createdAt: "desc" }, { id: "asc" }], take: PAGE_SIZE, select: { id: true, email: true } });
const ids = users.map((u) => u.id);

const balanceRows = await db.$queryRaw`
  SELECT DISTINCT ON (l."userId") l."userId", l."balanceAfter"
  FROM "CreditLedger" l
  WHERE l."userId" IN (${Prisma.join(ids)})
  ORDER BY l."userId", l."createdAt" DESC, l."id" DESC`;
console.log("RAW BALANCES", balanceRows);

const buildRows = await db.$queryRaw`
  SELECT p."userId",
         COUNT(*)::int AS "builds",
         COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS "succeeded",
         COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS "failed",
         COALESCE(SUM(b."costMicros"), 0)::bigint AS "costMicros",
         COALESCE(SUM(b."creditsCharged"), 0)::bigint AS "creditsCharged",
         MAX(b."createdAt") AS "lastBuildAt"
  FROM "Build" b
  JOIN "Project" p ON p."id" = b."projectId"
  WHERE p."userId" IN (${Prisma.join(ids)})
  GROUP BY p."userId"`;
console.log("RAW BUILD ROLLUP", buildRows);
console.log("KEYS", Object.keys(buildRows[0] ?? {}));

// Cross-check the DISTINCT ON balance against the per-user getBalance() Prisma path.
for (const u of users) {
  const latest = await db.creditLedger.findFirst({ where: { userId: u.id }, orderBy: { createdAt: "desc" } });
  const raw = balanceRows.find((r) => r.userId === u.id);
  console.log(
    `BALANCE CHECK ${u.email}: getBalance=${latest?.balanceAfter ?? 0} distinctOn=${raw?.balanceAfter ?? 0} ${
      (latest?.balanceAfter ?? 0) === (raw?.balanceAfter ?? 0) ? "OK" : "MISMATCH"
    }`,
  );
}

// ── Detail page query set for each user ──────────────────────────────────
for (const u of users) {
  const id = u.id;
  const [projects, builds, ledger, events, buildTotals, buildStatuses, granted, spent, ledgerTotal, buildTotal, eventTotal] =
    await Promise.all([
      db.project.findMany({ where: { userId: id }, orderBy: { createdAt: "desc" }, select: { id: true, name: true, slug: true, publishedAt: true, _count: { select: { builds: true, files: true, messages: true } } } }),
      db.build.findMany({ where: { project: { userId: id } }, orderBy: { createdAt: "desc" }, take: 100, select: { id: true, status: true, creditsCharged: true, costMicros: true, project: { select: { name: true } } } }),
      db.creditLedger.findMany({ where: { userId: id }, orderBy: [{ createdAt: "desc" }, { id: "desc" }], take: 250, select: { id: true, delta: true, reason: true, balanceAfter: true, createdAt: true, build: { select: { id: true, status: true, project: { select: { name: true } } } } } }),
      db.event.findMany({ where: { userId: id }, orderBy: { createdAt: "desc" }, take: 100, select: { id: true, name: true, props: true, createdAt: true } }),
      db.build.aggregate({ where: { project: { userId: id } }, _sum: { costMicros: true, creditsCharged: true, inputTokens: true, outputTokens: true } }),
      db.build.groupBy({ by: ["status"], where: { project: { userId: id } }, _count: { _all: true } }),
      db.creditLedger.aggregate({ where: { userId: id, delta: { gt: 0 } }, _sum: { delta: true } }),
      db.creditLedger.aggregate({ where: { userId: id, delta: { lt: 0 } }, _sum: { delta: true } }),
      db.creditLedger.count({ where: { userId: id } }),
      db.build.count({ where: { project: { userId: id } } }),
      db.event.count({ where: { userId: id } }),
    ]);

  const chrono = [...ledger].reverse();
  const broken = [];
  if (chrono.length > 0 && ledgerTotal <= 250 && chrono[0].balanceAfter !== chrono[0].delta) broken.push(chrono[0].id);
  for (let i = 1; i < chrono.length; i++) {
    if (chrono[i - 1].balanceAfter + chrono[i].delta !== chrono[i].balanceAfter) broken.push(chrono[i].id);
  }
  const chargedFailures = builds.filter((b) => b.status !== "SUCCEEDED" && b.creditsCharged > 0);
  const chargesOnBadBuilds = ledger.filter((l) => l.build !== null && l.delta < 0 && l.build.status !== "SUCCEEDED");

  console.log(`\nDETAIL ${u.email}`);
  console.log(`  projects=${projects.length} builds=${buildTotal} ledger=${ledgerTotal} events=${eventTotal}`);
  console.log(`  balance=${ledger[0]?.balanceAfter ?? 0} granted=${granted._sum.delta ?? 0} spent=${Math.abs(spent._sum.delta ?? 0)}`);
  console.log(`  cost=${buildTotals._sum.costMicros} creditsCharged=${buildTotals._sum.creditsCharged} statuses=${JSON.stringify(buildStatuses)}`);
  console.log(`  brokenLedgerRows=${broken.length} chargedFailures=${chargedFailures.length} chargesOnBadBuilds=${chargesOnBadBuilds.length}`);
  if (chargedFailures.length) console.log("  CHARGED FAILURES", chargedFailures.map((b) => `${b.id} ${b.status} +${b.creditsCharged}cr cost=${b.costMicros}`));
}

// Non-existent user id -> notFound path
console.log("\nMISSING USER ->", await db.user.findUnique({ where: { id: "does-not-exist" } }));

await db.$disconnect();

